<template><div class="page"><div class="page-header"><h2>押金明细</h2></div><el-card shadow="never" style="margin-bottom:16px"><div class="search-bar"><div class="field"><label>客户编码</label><el-input v-model="searchCustcd" placeholder="输入客户编码" size="small" style="width:150px" clearable @keyup.enter="doSearch"/></div><el-button type="primary" size="small" @click="doSearch" style="margin-left:auto">查询</el-button></div></el-card><el-card shadow="never"><el-table :data="items" v-loading="loading" stripe size="small" highlight-current-row @row-click="open"><el-table-column label="变更类型" width="100"><template #default="{row}">{{ row.c_type_nm || dcLabel(row.c_type) }}</template></el-table-column><el-table-column label="原金额" width="110" align="right"><template #default="{row}">¥{{ Number(row.old_a||0).toLocaleString() }}</template></el-table-column><el-table-column label="新金额" width="110" align="right"><template #default="{row}">¥{{ Number(row.new_a||0).toLocaleString() }}</template></el-table-column><el-table-column label="变更金额" width="110" align="right"><template #default="{row}">¥{{ Number(row.change_a||0).toLocaleString() }}</template></el-table-column><el-table-column prop="r_billid" label="关联单号" width="110"/><el-table-column label="确认金额" width="110" align="right"><template #default="{row}">¥{{ Number(row.confirm_a||0).toLocaleString() }}</template></el-table-column><el-table-column prop="updatetime" label="更新时间" width="110"/></el-table><AppPagination v-model:current-page="page" v-model:page-size="perPage" :total="total" style="margin-top:12px;justify-content:flex-end"/></el-card><el-dialog :title="'明细详情'" v-model="drawer" width="450px"><template v-if="detail"><el-descriptions :column="2" border size="small"><el-descriptions-item label="磁卡号">{{ detail.cust_card || custCard(detail.custcd) }}</el-descriptions-item><el-descriptions-item label="变更类型">{{ detail.c_type_nm || dcLabel(detail.c_type) }}</el-descriptions-item><el-descriptions-item label="原金额">¥{{ Number(detail.old_a||0).toLocaleString() }}</el-descriptions-item><el-descriptions-item label="新金额">¥{{ Number(detail.new_a||0).toLocaleString() }}</el-descriptions-item><el-descriptions-item label="变更金额">¥{{ Number(detail.change_a||0).toLocaleString() }}</el-descriptions-item><el-descriptions-item label="确认金额">¥{{ Number(detail.confirm_a||0).toLocaleString() }}</el-descriptions-item><el-descriptions-item label="关联单号">{{ detail.r_billid||'-' }}</el-descriptions-item><el-descriptions-item label="更新时间">{{ detail.updatetime||'-' }}</el-descriptions-item><el-descriptions-item label="备注" :span="2">{{ detail.remark||'-' }}</el-descriptions-item></el-descriptions></template></el-dialog></div></template>
<script setup lang="ts">import {ref} from 'vue';import AppPagination from '@/components/common/AppPagination.vue';import {useListPage} from '@/composables/useListPage';import {useDetailDrawer} from '@/composables/useDetailDrawer';import {useCustomerCards} from '@/composables/useCustomerCards';import {useDict} from '@/composables/useDict';import {fetchAllDepositDetails,fetchDepositDetails} from '@/api/deposit';import type {DepositRecord} from '@/api/deposit'
const searchCustcd=ref('')
const{items,loading,page,perPage,total,onSearch}=useListPage<DepositRecord>((p?:Record<string,string>)=>{const q=p||{};if(!q.custcd&&searchCustcd.value)q.custcd=searchCustcd.value;return q.custcd?fetchDepositDetails(q.custcd,q):fetchAllDepositDetails(q)})
const{drawer,detail,open}=useDetailDrawer<DepositRecord>();const{custCard}=useCustomerCards();const{dictLabel:dcLabel}=useDict('PL')
function doSearch(){if(searchCustcd.value){onSearch({custcd:searchCustcd.value})}}</script>
<style scoped>.page{padding:0}.page-header{display:flex;justify-content:space-between;margin-bottom:16px}.page-header h2{font-size:18px;font-weight:600;margin:0}.search-bar{display:flex;gap:12px;align-items:center}.field{display:flex;align-items:center;gap:6px}.field label{font-size:13px;color:#606266}</style>
